"""Check split groups in WebKitGTK while retaining real terminal controllers."""
def check(client, session, first, wait_for, mark):
    client.click('[aria-label="Session and tab menu"]')
    client.click("//details[@open]//button[@title='Open a new tab'][normalize-space()='Stream']", 'xpath')
    second = wait_for(lambda: client.js("const id=Number(document.querySelector('.session-pane:not([hidden]) [role=tab][aria-selected=true]')?.id.slice(4));return id && id!==arguments[0] ? id : null", first), 'new terminal selected')
    wait_for(lambda: client.state(second), 'second split terminal')
    client.js("window.splitOriginal=document.getElementById('tab-panel-'+arguments[0]); document.getElementById('tab-'+arguments[0]).dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,clientX:150,clientY:100}))", second)
    client.click("//div[@role='menu']//button[normalize-space()='Split Right']", 'xpath')
    wait_for(lambda: client.js("return document.querySelectorAll('.session-pane:not([hidden]) .group-header').length===2"), 'two group headers')
    assert client.js("return document.querySelector('.session-pane:not([hidden])').classList.contains('split-right')")
    assert client.js("return window.splitOriginal===document.getElementById('tab-panel-'+arguments[0])", second)
    assert client.js("return [...document.querySelectorAll('.session-pane:not([hidden]) .group-content:not([hidden])')].length===2")
    mark('Context-menu split displays two terminal panels without replacing the moved panel')
    client.js("document.getElementById('tab-'+arguments[0]).dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,clientX:150,clientY:100}))", second)
    client.click("//div[@role='menu']//button[normalize-space()='Change Split Orientation']", 'xpath')
    wait_for(lambda: client.js("return !!document.querySelector('.session-pane:not([hidden]).split-below')"), 'stacked groups')
    client.invoke('select_tab', {'id': first})
    client.js("document.getElementById('tab-'+arguments[0]).click()", first)
    wait_for(lambda: client.js("return [...document.querySelectorAll('.session-pane:not([hidden]) .group-content:not([hidden])')].length===2"), 'independent visible selections')
    client.js("document.getElementById('tab-'+arguments[0]).dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,clientX:150,clientY:100}))", second)
    client.click("//div[@role='menu']//button[normalize-space()='Move to Other Group']", 'xpath')
    wait_for(lambda: client.js("return !document.querySelector('.session-pane:not([hidden]) .split-separator')"), 'empty group merged')
    assert client.js("return window.splitOriginal===document.getElementById('tab-panel-'+arguments[0])", second)
    mark('Orientation change and moving the last group tab preserve its terminal panel and merge groups')
    client.js("document.getElementById('tab-'+arguments[0]).click()", first)
    # Exercise React's drag handlers in WebKitGTK; physical pointer dragging is separate.
    client.js("window.splitDrag=new DataTransfer(); document.getElementById('tab-'+arguments[0]).dispatchEvent(new DragEvent('dragstart',{bubbles:true,dataTransfer:window.splitDrag}))", second)
    client.js("const p=document.querySelector('.session-pane:not([hidden]) .group-content:not([hidden])'); const r=p.getBoundingClientRect(); p.dispatchEvent(new DragEvent('dragover',{bubbles:true,cancelable:true,dataTransfer:window.splitDrag,clientX:r.right-5,clientY:r.top+r.height/2}))")
    wait_for(lambda: client.js("return !!document.querySelector('.preview-right')"), 'right split preview')
    client.js("const p=document.querySelector('.session-pane:not([hidden]) .group-content:not([hidden])'); p.dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:window.splitDrag}))")
    wait_for(lambda: client.js("return !!document.querySelector('.session-pane:not([hidden]).split-right')"), 'drag-created split')
    assert client.js("return document.querySelectorAll('.session-pane:not([hidden]) .group-header').length===2")
    client.js("document.querySelector('.session-pane:not([hidden]) .split-separator').dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:'ArrowRight'}))")
    wait_for(lambda: client.js("return document.querySelector('.session-pane:not([hidden]) .split-separator').getAttribute('aria-valuenow')==='55'"), 'keyboard divider resize')
    client.js("document.getElementById('tab-'+arguments[0]).dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,clientX:150,clientY:100}))", second)
    client.click("//div[@role='menu']//button[normalize-space()='Join Groups']", 'xpath')
    wait_for(lambda: client.js("return !document.querySelector('.session-pane:not([hidden]) .split-separator')"), 'explicit join')
    client.js("document.getElementById('tab-'+arguments[0]).click()", first)
    mark('WebKitGTK drag events preview and create a right split; explicit join retains both tabs')
    client.js("document.getElementById('tab-'+arguments[0]).dispatchEvent(new DragEvent('dragstart',{bubbles:true,dataTransfer:window.splitDrag}))", second)
    client.js("const p=document.querySelector('.session-pane:not([hidden]) .group-content:not([hidden])'); const r=p.getBoundingClientRect(); p.dispatchEvent(new DragEvent('dragover',{bubbles:true,cancelable:true,dataTransfer:window.splitDrag,clientX:r.left+r.width/2,clientY:r.bottom-5}))")
    wait_for(lambda: client.js("return !!document.querySelector('.preview-below')"), 'bottom split preview')
    client.js("document.getElementById('tab-'+arguments[0]).dispatchEvent(new DragEvent('dragend',{bubbles:true,dataTransfer:window.splitDrag}))", second)
    wait_for(lambda: client.js("return !document.querySelector('.split-preview')"), 'cancelled drag clears preview')
    assert client.js("return !document.querySelector('.session-pane:not([hidden]) .split-separator')")
    mark('Bottom drop zone previews a stacked split; cancelled drag leaves the layout unchanged')
    client.invoke('close_tab', {'id': second, 'confirmed': True})
    client.js("document.getElementById('tab-'+arguments[0]).click()", first)
    wait_for(lambda: client.js("return !document.getElementById('tab-'+arguments[0])", second), 'split fixture terminal closed')
